package net.civeira.phylax.feature.observe.observedalert.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedalert.domain.ObservedAlert;
import net.civeira.phylax.feature.observe.observedalert.domain.valueobject.LinkVO;

class LinkValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of link of observed alert")
  void test_link_value_holder_assign_plain_value() {
    Object holder = new Object();
    LinkValueHolder<Object> value = new LinkValueHolder<>(holder);
    Assertions.assertSame(holder, value.link("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getLinkValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getLink().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.linkNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getLinkValue().isPresent(), "A null value object must be stored");
    Assertions.assertFalse(value.getLink().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of link of observed alert")
  void test_link_value_holder_assign_value_object() {
    Object holder = new Object();
    LinkValueHolder<Object> value = new LinkValueHolder<>(holder);
    LinkVO vo = LinkVO.from("one");
    Assertions.assertFalse(value.getLinkValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.link(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getLinkValue().orElseThrow());
    Assertions.assertSame(holder, value.link(Optional.empty()));
    Assertions.assertFalse(value.getLinkValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.link(Optional.of(vo)));
    Assertions.assertSame(vo, value.getLinkValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of link of observed alert against the original")
  void test_link_value_holder_read() {
    Object holder = new Object();
    LinkValueHolder<Object> value = new LinkValueHolder<>(holder);
    LinkVO vo = LinkVO.from("one");
    LinkVO other = LinkVO.from("one");
    ObservedAlert original = Mockito.mock(ObservedAlert.class);
    Mockito.when(original.getLinkValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readLink(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readLink(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.link(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readLink(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readLink(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of link of observed alert")
  void test_link_value_holder_unset() {
    Object holder = new Object();
    LinkValueHolder<Object> value = new LinkValueHolder<>(holder);
    LinkVO vo = LinkVO.from("one");
    value.link(vo);
    Assertions.assertSame(holder, value.unsetLinkIfMatches("link_other"));
    Assertions.assertTrue(value.getLinkValue().isPresent(), "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetLinkIfMatches("link"));
    Assertions.assertFalse(value.getLinkValue().isPresent(), "The field name must clear the value");
    value.link(vo);
    Assertions.assertSame(holder, value.unsetLink());
    Assertions.assertFalse(value.getLinkValue().isPresent(), "Unset must clear the value");
  }
}
